package ntcanvas_test

import (
	"bytes"
	"nimbleterminal.dev/ntcanvas/internal/parity"
	"os"
	"testing"
)

// The expected output is generated by unmodified NTCharts at the pinned
// extraction revision, not by this implementation. CI never regenerates it.
func TestUpstreamParity(t *testing.T) {
	want, err := os.ReadFile("testdata/upstream/snapshot.json")
	if err != nil {
		t.Fatal(err)
	}
	got, err := parity.Snapshot()
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(bytes.TrimSpace(got), bytes.TrimSpace(want)) {
		t.Fatalf("upstream behavior differs\nwant:\n%s\ngot:\n%s", want, got)
	}
}
